// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint256 a1, uint256 a2, address actor, uint256 t1, uint256 t2) public {
        vm.assume(a1 <= VALUE_CAP);
        vm.assume(a2 <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        a1 = bound(a1, 0, 100 ether);
        a2 = bound(a2, 0, 100 ether);
        t1 = bound(t1, 1, 1e12);
        t2 = bound(t2, 1, 1e12);
        vm.deal(actor, a1 + a2);
        vm.warp(t1);
        vm.prank(actor);
        c.Put{value: a1}(t1);
        vm.warp(t2);
        vm.prank(actor);
        c.Put{value: a2}(t2);
        (uint256 unlockTime, uint256 bal) = c.Acc(actor);
        assertTrue(bal == a1 + a2 && unlockTime >= t2);
    }
}
